use crate::{model::*,unit_support::*,wm036 as b};
use crate::jc029_tests::pass_top;
#[test]fn wm036_original_closed_fields_and_nonasset(){let d=crate::catalog::card(b::ID);assert!(!d.supported);assert!(crate::catalog::runtime_implemented(d));assert_eq!(d.cost,1);assert_eq!(d.loyalty,["红色","红色"]);assert_eq!(d.magic,"鲜血");assert_eq!(d.subtypes,["仪式","灾难"]);assert_current_serial_catalog();crate::rules::validate_definitions(crate::rules::definitions()).unwrap();let mut g=game();let c=held(&mut g,b::ID,0);reject(&mut g,0,Action{card_id:Some(c.clone()),..Action::new("asset")});assert!(!g.legal_actions(0).iter().any(|a|a.action.kind=="asset"&&a.action.card_id.as_ref()==Some(&c)));}
fn play(g:&mut Game){fund(g,0,"JC049",2);let c=held(g,b::ID,0);act(g,0,Action{card_id:Some(c),..Action::new("play")});pass_top(g);}
#[test]fn wm036_real_paid_spell_each_player_current_character_sacrificed(){let mut g=game();let ids=(0..4).map(|s|field(&mut g,"JC029",s)).collect::<Vec<_>>();play(&mut g);for s in 0..4{assert_eq!(g.pending.as_ref().unwrap().seat,s);choose(&mut g,vec![ids[s].clone()]);}assert!(g.pending.is_none());assert!(g.regions[0].cards.is_empty());for s in 0..4{assert!(g.players[s].graveyard.iter().any(|c|c.definition=="JC029"));}assert!(g.players[0].graveyard.iter().any(|c|c.definition==b::ID));restore(&mut g);}
fn corrupt(g:&Game){assert!(Game::from_persisted(&serde_json::to_string(g).unwrap()).is_err());let r=crate::room::RoomEnvelope::from_game(g.clone());assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
fn shown_with(own:bool,shield:bool)->(Game,String){let mut g=game();let owner=if own{0}else{1};g.players[owner].society_zone.card=Some(g.make_card("MSJC13",owner));let target=field(&mut g,"JC029",2);g.board_mut(&target).unwrap().shield=u32::from(shield);let cards=[b::ID,"JC125","JC125","JC125"].iter().enumerate().map(|(s,id)|held(&mut g,id,s)).collect::<Vec<_>>();fund(&mut g,0,"JC125",2);let source=held(&mut g,"BQ090",0);act(&mut g,0,Action{card_id:Some(source),ability_id:Some(crate::import20_contest::HAND.into()),..Action::new("activate")});pass_top(&mut g);for c in cards{assert_eq!(g.pending.as_ref().unwrap().choice.kind,crate::mystic_contest::COMMIT_KIND);choose(&mut g,vec![c]);}for _ in 0..8{if g.pending.as_ref().is_some_and(|p|p.choice.kind==crate::mystic_contest::REWARD_KIND){choose(&mut g,vec![])}else{break}}assert_eq!(g.mystic_history[0].shown[0].value,3);(g,target)}
fn shown(own:bool)->(Game,String){shown_with(own,false)}
#[test]fn wm036_shown_bonus_unconditional_time_optional_personal_and_shielded(){let(g,_)=shown(false);assert!(g.pending.is_none());for take in [false,true]{let(mut g,target)=shown(true);assert_eq!(g.pending.as_ref().unwrap().choice.kind,b::TIME_KIND);assert_eq!(g.pending.as_ref().unwrap().choice.min,Some(0));for s in 1..4{assert!(g.view(s).pending_choice.is_none());}choose(&mut g,if take{vec![target.clone()]}else{vec![]});assert_eq!(g.board(&target).unwrap().1.time_markers,u32::from(take));assert!(g.mystic_contest.is_none());restore(&mut g);}}
#[test]fn wm036_sacrifice_omits_hidden_core_and_empty_players_and_obeys_current_control(){let mut g=game();let foreign=field(&mut g,"JC029",1);g.add_control(&foreign,0,ControlLifetime::TurnEnd{turn:g.turn},SubtypeChange::None);let hidden=field(&mut g,"JC125",2);g.board_mut(&hidden).unwrap().face_down=true;g.players[3].society_zone.card=Some(g.make_card("MSBQ02",3));let core=g.make_card("BQ046",3);g.core_zones.push(crate::core_zone::CoreZone{owner:3,definition:"BQ046".into(),card:Some(core),rest:2});play(&mut g);assert_eq!(g.pending.as_ref().unwrap().seat,0);assert_eq!(g.pending.as_ref().unwrap().choice.options.len(),1);choose(&mut g,vec![foreign]);assert!(g.pending.is_none());assert!(g.players[1].graveyard.iter().any(|c|c.definition=="JC029"));assert!(g.board(&hidden).is_some());assert!(g.core_zones[0].card.is_some());restore(&mut g);let mut g=game();play(&mut g);assert!(g.pending.is_none());assert!(g.players[0].graveyard.iter().any(|c|c.definition==b::ID));}
#[test]fn wm036_paid_stack_target_change_refreshes_choices_without_refunding(){let mut g=game();let target=field(&mut g,"JC029",0);fund(&mut g,0,"JC049",2);let c=held(&mut g,b::ID,0);act(&mut g,0,Action{card_id:Some(c),..Action::new("play")});let resources=g.resources(0);g.remove_dead(&target,RemovalCause::Destroy);restore(&mut g);pass_top(&mut g);assert!(g.pending.is_none());assert_eq!(g.resources(0),resources);}
#[test]fn wm036_restore_rejects_wrong_source_missing_frame_seat_order_and_shown_receipt(){let mut g=game();for s in 0..4{field(&mut g,"JC029",s);}fund(&mut g,0,"JC049",2);let c=held(&mut g,b::ID,0);act(&mut g,0,Action{card_id:Some(c),..Action::new("play")});let mut bad=g.clone();bad.stack.last_mut().unwrap().frame=None;corrupt(&bad);let mut bad=g.clone();bad.stack.last_mut().unwrap().frame.as_mut().unwrap().source.card.definition="JC001".into();corrupt(&bad);pass_top(&mut g);let mut bad=g.clone();if let ChoiceResolution::Frame{frame,..}=&mut bad.pending.as_mut().unwrap().resolution{frame.steps.swap(0,1);}corrupt(&bad);let p=g.pending.clone().unwrap();reject(&mut g,1,Action{choice_id:Some(p.choice.id),selected:Some(vec![p.choice.options[0].id.clone()]),..Action::new("choose")});let(mut g,_)=shown(true);if let ChoiceResolution::Frame{frame,..}=&mut g.pending.as_mut().unwrap().resolution{frame.source.card.definition="WM037".into();}corrupt(&g);}
#[test]fn wm036_sacrifice_waits_for_actual_blood_departure_before_next_player(){let mut g=game();g.players[0].society_zone.card=Some(g.make_card("MSBQ01",0));let host=field(&mut g,"JC031",0);let card=g.make_card("XQ14",0);g.attachments.push(Attachment{card,host_id:host.clone()});let other=field(&mut g,"JC029",1);play(&mut g);choose(&mut g,vec![host]);let mut sealed=false;for _ in 0..80{if let Some(p)=g.pending.clone(){if matches!(&p.resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==crate::msbq01::KEY){sealed=true;choose(&mut g,vec!["accept".into()]);}else if p.choice.options.iter().any(|o|o.id==other){assert!(sealed);assert!(g.sealed_cards.iter().any(|s|s.card.definition=="XQ14"));choose(&mut g,vec![other.clone()]);}else{resolve_choice(&mut g);}}else if !g.stack.is_empty(){pass(&mut g);}else{break}}assert!(sealed);assert!(g.board(&other).is_none());restore(&mut g);}
fn construct(seed:u64)->Game{use crate::{catalog,deck};let mut d=deck::preset("watchers").unwrap();d.id="closed-wm036-natural".into();d.society_id=Some("MSJC13".into());d.core_card_id=None;d.cards=[(b::ID,3),("BQ090",3),("JC042",3),("JC049",3),("JC047",3),("XQ17",3),("JC045",3),("JC043",3),("JC048",3),("JC125",23)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id==b::ID).unwrap().supported=true;let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id=="MSJC13").unwrap().card.supported=true;let d=deck::validate_with_registry(d,&cards,&societies).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("wm036-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
fn pending(t:&mut crate::abi112_review_play_tests::Trace){let g=&t.room.game;let p=g.pending.clone().unwrap();if matches!(p.resolution,ChoiceResolution::Forecast{..}|ChoiceResolution::Frame{choice:FrameChoice::Forecast{..},..}){t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(p.choice.options.iter().map(|o|o.id.clone()).collect()),bottom:Some(vec![]),..Action::new("choose")});return}let ids=if p.choice.kind==crate::mystic_contest::COMMIT_KIND{let wanted=if p.seat==0{b::ID}else{"JC125"};vec![p.choice.options.iter().find(|o|g.players[p.seat].hand.iter().any(|c|c.id==o.id&&c.definition==wanted)).unwrap().id.clone()]}else if p.choice.kind==b::TIME_KIND{vec![p.choice.options[0].id.clone()]}else{let mut v=p.choice.options.iter().collect::<Vec<_>>();v.sort_by_key(|o|g.players[p.seat].hand.iter().find(|c|c.id==o.id).map(|c|if matches!(c.definition.as_str(),"WM036"|"BQ090"){2}else if c.definition=="JC125"{0}else{1}).unwrap_or(0));v.into_iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()};t.choose(ids);}
fn duplicates(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);s["duplicate"]=serde_json::to_value(d).unwrap();}v}
#[test]fn wm036_natural_paid_four_sacrifices_then_real_shown_time_export(){use crate::abi112_review_play_tests::Trace;let(seed,g)=(1..4097).find_map(|seed|{let g=construct(seed);let mut p=g.clone();while p.pending.is_some(){choose(&mut p,vec![]);}let h=&p.players[0].hand;(h.iter().filter(|c|c.definition==b::ID).count()>=2&&h.iter().any(|c|c.definition=="BQ090")).then_some((seed,g))}).unwrap();let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"wm036-natural-four-sacrifices-and-shown-time".into(),936);let(mut played,mut contest)=(false,false);let mut deployed=[false;4];for _ in 0..2200{if t.room.game.pending.is_some(){pending(&mut t);continue}if contest&&t.room.game.mystic_contest.is_none()&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break}if !t.room.game.stack.is_empty()||t.room.pacing.window.is_some(){t.pass();continue}let g=&t.room.game;let mut next=None;for seat in 0..4{let legal=g.legal_actions(seat);let a=if seat==0&&g.players[0].assets.len()<2{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&crate::catalog::card(&c.definition).color=="红"&&c.definition!=b::ID)))}else if !played&&!deployed[seat]||played&&seat==0&&!g.regions.iter().flat_map(|r|&r.cards).any(|c|c.controller==0&&!c.face_down){legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[seat].hand.iter().any(|c|&c.id==id&&c.definition=="JC125")))}else if seat==0&&!played&&deployed.iter().all(|x|*x){legal.iter().find(|a|a.action.kind=="play"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==b::ID)))}else if seat==0&&played&&g.players[0].hand.iter().any(|c|c.definition==b::ID){legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::import20_contest::HAND))}else{None};if let Some(a)=a{next=Some((seat,a.action.clone()));break}}if let Some((seat,a))=next{match a.kind.as_str(){"deploy"=>deployed[seat]=true,"play"=>played=true,"activate"=>contest=true,_=>()}t.action(seat,a);}else{t.pass();}}
assert!(played&&contest,"natural stages {played}/{contest}, turn {}",t.room.game.turn);assert!(t.room.game.regions.iter().flat_map(|r|&r.cards).any(|c|c.time_markers==1));for s in 0..4{assert!(t.room.game.players[s].graveyard.iter().any(|c|c.definition=="JC125"));}let mut natural=t.value();natural["construction"]=serde_json::json!({"deck":deck,"seed":seed,"privateRegistryCandidates":[b::ID,"MSJC13"],"noLayoutOrResourceMutation":true});let(g,_)=shown(true);let mut t=Trace::new_preserving_rng(g,"wm036-prepared-real-shown-decline".into(),937);t.choose(vec![]);assert!(t.room.game.mystic_contest.is_none());let cases=vec![duplicates(natural),duplicates(t.value())];if let Ok(path)=std::env::var("WM036_NATIVE_OUT"){use sha2::{Digest,Sha256};let mut binding=crate::bq052_tests::source_bindings();for(n,s)in[("rust-game/src/wm036.rs",include_str!("wm036.rs")),("rust-game/src/wm036_tests.rs",include_str!("wm036_tests.rs"))]{binding["files"][n]=format!("{:x}",Sha256::digest(s.as_bytes())).into();}std::fs::write(path,serde_json::to_vec(&serde_json::json!({"catalog":crate::catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}

#[test]fn wm036_shown_time_consumes_real_enemy_shield_without_marker(){let(mut g,target)=shown_with(true,true);choose(&mut g,vec![target.clone()]);assert_eq!(g.board(&target).unwrap().1.time_markers,0);assert_eq!(g.board(&target).unwrap().1.shield,0);restore(&mut g);}
